def step(view, state):
    if not state:
        state = {"step_count": 0}

    if "model_observation" not in view:
        request = dict(view["baseline_request"])

        if view.get("service_experience"):
            if "messages" in request:
                k_msg = {
                    "role": "system",
                    "content": "Service Experience Guide: " + str(view["service_experience"])
                }
                request["messages"].insert(1, k_msg)

        return {"kind": "MODEL", "state": state, "request": request}

    state["step_count"] += 1
    obs = view["model_observation"]

    return {"kind": "ACTION", "state": state, "action": obs}

